function lineOf(source, fragment) {
  const start = source.indexOf(fragment);
  assert(start >= 0 && source.indexOf(fragment, start + 1) === -1, 'Unique frozen assertion anchor: ' + fragment);
  return source.slice(0,start).split('\n').length;
}

